Future<void> save()async{final c=ref.read(appControllerProvider);final targetPetId=petId??c.selectedPet?.id;if(title.text.trim().isEmpty||targetPetId==null)return;final parsedInterval=int.tryParse(interval.text);if(repeat=='interval'&&(parsedInterval==null||parsedInterval<1||parsedInterval>365)){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Choose a repeat interval between 1 and 365 days.')));return;}final r=Reminder(id:widget.reminder?.id??DateTime.now().microsecondsSinceEpoch.toString(),petId:targetPetId,title:title.text.trim(),category:category,dueAt:due,repeat:repeat,weekdays:repeat=='weekdays'?(weekdays.isEmpty?[due.weekday]:weekdays.toList()):weekdays.toList(),intervalDays:parsedInterval??1,monthEndPolicy:monthEndPolicy,note:note.text.trim(),enabled:widget.reminder?.enabled??true);await c.saveReminder(r);if(!mounted)return;final enabled=await LocalNotificationService.instance.notificationsEnabled();if(!enabled){final allow=await showDialog<bool>(context:context,builder:(d)=>AlertDialog(title:const Text('Get a helpful reminder'),content:const Text('Allow notifications so PawPal can remind you about this task. The reminder will still appear in your in-app schedule if you choose not to allow notifications.'),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('Not now')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('Enable notifications'))]));if(allow==true){final granted=await LocalNotificationService.instance.requestPermission();if(granted)await c.resyncNotifications();}}if(mounted)Navigator.pop(context);}
@override Widget build(BuildContext context){final c=ref.watch(appControllerProvider);return Scaffold(appBar:AppBar(title:Text(widget.reminder==null?'New reminder':'Edit reminder')),body:ListView(padding:const EdgeInsets.all(20),children:[DropdownButtonFormField<String>(value:petId??c.selectedPet?.id,decoration:const InputDecoration(labelText:'Pet'),items:c.pets.map((p)=>DropdownMenuItem(value:p.id,child:Text(p.archived?'${p.name} · archived':p.name))).toList(),onChanged:(v)=>setState(()=>petId=v)),const SizedBox(height:12),TextField(controller:title,decoration:const InputDecoration(labelText:'Task title *')),const SizedBox(height:12),DropdownButtonFormField<String>(value:category,decoration:const InputDecoration(labelText:'Task type'),items:['Feeding','Water refresh','Walk','Litter / yard cleanup','Grooming','Nail trim','Dental routine','Training','Appointment','Vaccination follow-up','Medication (owner-entered)','Custom'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>setState(()=>category=v!)),ListTile(contentPadding:EdgeInsets.zero,title:const Text('Date and time'),subtitle:Text(due.toLocal().toString().substring(0,16)),onTap:()async{final d=await showDatePicker(context:context,initialDate:due,firstDate:DateTime(2020),lastDate:DateTime(2100));if(d==null)return;final t=await showTimePicker(context:context,initialTime:TimeOfDay.fromDateTime(due));if(t!=null)setState(()=>due=DateTime(d.year,d.month,d.day,t.hour,t.minute));}),DropdownButtonFormField<String>(value:repeat,decoration:const InputDecoration(labelText:'Repeat'),items:const[DropdownMenuItem(value:'once',child:Text('Does not repeat')),DropdownMenuItem(value:'daily',child:Text('Daily')),DropdownMenuItem(value:'weekly',child:Text('Weekly')),DropdownMenuItem(value:'weekdays',child:Text('Selected weekdays')),DropdownMenuItem(value:'monthly',child:Text('Monthly')),DropdownMenuItem(value:'interval',child:Text('Every N days'))],onChanged:(v)=>setState(()=>repeat=v!)),if(repeat=='weekdays